namespace TutorFlow.Domain.Academico;

/// <summary>
/// Dato academico corrupto (nota fuera de [0.0, 5.0], clases programadas &lt;= 0 o nulas, creditos &lt;= 0, etc.; SPEC 5.1, 5.3).
/// Nunca se recorta ni se inventa un valor: quien lo captura informa el error.
/// </summary>
public sealed class DatoAcademicoInvalidoException : Exception
{
    public DatoAcademicoInvalidoException(string message)
        : base(message)
    {
    }
}

namespace TutorFlow.Domain.Academico;

/// <summary>Redondeo academico: siempre <see cref="MidpointRounding.AwayFromZero"/> sobre decimal (SPEC 5.1, 5.4).</summary>
public static class Redondeo
{
    /// <summary>Definitiva: 1 decimal.</summary>
    public static decimal Definitiva(decimal bruta) => Math.Round(bruta, 1, MidpointRounding.AwayFromZero);

    /// <summary>Promedio ponderado: 2 decimales.</summary>
    public static decimal Promedio(decimal valor) => Math.Round(valor, 2, MidpointRounding.AwayFromZero);

    /// <summary>Aporte acumulado: 2 decimales.</summary>
    public static decimal Aporte(decimal valor) => Math.Round(valor, 2, MidpointRounding.AwayFromZero);
}

namespace TutorFlow.Domain.Academico;

/// <summary>Validacion de notas: rango [0.0, 5.0] (SPEC 5.1). Fuera de rango = dato corrupto; no se recorta.</summary>
public static class Nota
{
    public const decimal Minima = 0.0m;
    public const decimal Maxima = 5.0m;

    public static bool EsValida(decimal valor) => valor >= Minima && valor <= Maxima;

    public static decimal Validar(decimal valor, string campo)
    {
        if (!EsValida(valor))
        {
            throw new DatoAcademicoInvalidoException($"Nota fuera de rango [0.0, 5.0] en '{campo}'.");
        }

        return valor;
    }
}

namespace TutorFlow.Domain.Academico;

/// <summary>Calculo de la definitiva a partir de los tres cortes (SPEC 5.1, 5.2). Pesos 30/30/40.</summary>
public static class Cortes
{
    public const decimal Peso1 = 0.3m;
    public const decimal Peso2 = 0.3m;
    public const decimal Peso3 = 0.4m;

    /// <summary>Definitiva con los tres cortes calificados.</summary>
    public static decimal Definitiva(decimal corte1, decimal corte2, decimal corte3)
    {
        Nota.Validar(corte1, nameof(corte1));
        Nota.Validar(corte2, nameof(corte2));
        Nota.Validar(corte3, nameof(corte3));
        return Redondeo.Definitiva((Peso1 * corte1) + (Peso2 * corte2) + (Peso3 * corte3));
    }

    /// <summary>Definitiva, o null si algun corte es null (asignatura en curso).</summary>
    public static decimal? Definitiva(decimal? corte1, decimal? corte2, decimal? corte3)
    {
        Validar(corte1, nameof(corte1));
        Validar(corte2, nameof(corte2));
        Validar(corte3, nameof(corte3));
        if (corte1 is null || corte2 is null || corte3 is null)
        {
            return null;
        }

        return Definitiva(corte1.Value, corte2.Value, corte3.Value);
    }

    /// <summary>Aporte acumulado = suma(peso x corte calificado), 2 decimales.</summary>
    public static decimal AporteAcumulado(decimal? corte1, decimal? corte2, decimal? corte3)
    {
        Validar(corte1, nameof(corte1));
        Validar(corte2, nameof(corte2));
        Validar(corte3, nameof(corte3));
        var suma = (corte1 is null ? 0m : Peso1 * corte1.Value)
            + (corte2 is null ? 0m : Peso2 * corte2.Value)
            + (corte3 is null ? 0m : Peso3 * corte3.Value);
        return Redondeo.Aporte(suma);
    }

    /// <summary>Porcentaje evaluado (0..100): suma de los pesos de los cortes calificados.</summary>
    public static int PorcentajeEvaluado(decimal? corte1, decimal? corte2, decimal? corte3)
    {
        Validar(corte1, nameof(corte1));
        Validar(corte2, nameof(corte2));
        Validar(corte3, nameof(corte3));
        return (corte1 is null ? 0 : 30) + (corte2 is null ? 0 : 30) + (corte3 is null ? 0 : 40);
    }

    private static void Validar(decimal? corte, string campo)
    {
        if (corte is not null)
        {
            Nota.Validar(corte.Value, campo);
        }
    }
}

namespace TutorFlow.Domain.Academico;

/// <summary>Perdida por inasistencia (Reglamento 2025, Art. 11; SPEC 5.3). Aritmetica entera.</summary>
public static class Inasistencia
{
    /// <summary>
    /// true si inasistencias x 100 &gt; 15 x clases; false si no; null si no hay registro de inasistencias.
    /// Clases nulas o &lt;= 0, o inasistencias negativas = dato corrupto.
    /// </summary>
    public static bool? Pierde(int? clasesProgramadas, int? inasistencias)
    {
        if (clasesProgramadas is null || clasesProgramadas.Value <= 0)
        {
            throw new DatoAcademicoInvalidoException("clasesProgramadas debe ser un entero positivo.");
        }

        if (inasistencias is null)
        {
            return null;
        }

        if (inasistencias.Value < 0)
        {
            throw new DatoAcademicoInvalidoException("inasistencias no puede ser negativo.");
        }

        return (long)inasistencias.Value * 100 > 15L * clasesProgramadas.Value;
    }
}

namespace TutorFlow.Domain.Academico;

/// <summary>
/// Asignatura de un estudiante en el periodo. Valida los datos al construirse (dato corrupto -> excepcion tipada)
/// y expone las reglas de SPEC 5.1-5.6. Es pura: no hace E/S.
/// </summary>
public sealed class AsignaturaPeriodo
{
    public const decimal NotaAprobatoria = 3.0m;
    public const decimal NotaMinimaHabilitacion = 2.0m;

    public AsignaturaPeriodo(
        string codigo,
        int creditos,
        decimal? corte1,
        decimal? corte2,
        decimal? corte3,
        int? clasesProgramadas,
        int? inasistencias)
    {
        ArgumentException.ThrowIfNullOrEmpty(codigo);
        if (creditos <= 0)
        {
            throw new DatoAcademicoInvalidoException("creditos debe ser un entero positivo.");
        }

        Codigo = codigo;
        Creditos = creditos;
        Corte1 = corte1;
        Corte2 = corte2;
        Corte3 = corte3;
        ClasesProgramadas = clasesProgramadas;
        Inasistencias = inasistencias;

        // Valida cortes y asistencia en construccion (fail-closed ante datos corruptos).
        Definitiva = Cortes.Definitiva(corte1, corte2, corte3);
        PierdePorInasistencia = Inasistencia.Pierde(clasesProgramadas, inasistencias);
    }

    public string Codigo { get; }

    public int Creditos { get; }

    public decimal? Corte1 { get; }

    public decimal? Corte2 { get; }

    public decimal? Corte3 { get; }

    public int? ClasesProgramadas { get; }

    public int? Inasistencias { get; }

    /// <summary>Definitiva redondeada; null si algun corte esta pendiente.</summary>
    public decimal? Definitiva { get; }

    public decimal AporteAcumulado => Cortes.AporteAcumulado(Corte1, Corte2, Corte3);

    public int PorcentajeEvaluado => Cortes.PorcentajeEvaluado(Corte1, Corte2, Corte3);

    /// <summary>false si no hay registro de inasistencias (SPEC 5.3, D-06).</summary>
    public bool DatoAsistenciaDisponible => Inasistencias is not null;

    /// <summary>null = desconocido (sin registro).</summary>
    public bool? PierdePorInasistencia { get; }

    /// <summary>0.0 si pierde por inasistencia (sin importar los cortes); si no, la definitiva (null si en curso).</summary>
    public decimal? DefinitivaEfectiva => PierdePorInasistencia == true ? 0.0m : Definitiva;

    /// <summary>Perdida: definitiva efectiva &lt; 3.0 o perdida por inasistencia (Art. 5).</summary>
    public bool Perdida => PierdePorInasistencia == true || (DefinitivaEfectiva is { } d && d < NotaAprobatoria);

    /// <summary>Aprobada: definitiva efectiva &gt;= 3.0 (Art. 5).</summary>
    public bool Aprobada => DefinitivaEfectiva is { } d && d >= NotaAprobatoria;

    /// <summary>Habilitable = perdida y definitiva &gt;= 2.0 y no perdida por inasistencia (Art. 6-7).</summary>
    public bool Habilitable => Perdida
        && PierdePorInasistencia != true
        && Definitiva is { } d
        && d >= NotaMinimaHabilitacion;
}

namespace TutorFlow.Domain.Academico;

public enum SituacionAcademica
{
    Normal,
    PruebaAcademica,
    NoDisponible,
}

/// <summary>Reglas agregadas del periodo (SPEC 5.4, 5.7).</summary>
public static class ResumenAcademico
{
    public const decimal UmbralPruebaAcademica = 3.0m;

    /// <summary>
    /// Promedio ponderado por creditos de las definitivas efectivas (ya redondeadas), 2 decimales AwayFromZero.
    /// Solo entran las asignaturas con definitiva efectiva (las perdidas por inasistencia entran con 0.0).
    /// null = "no disponible" si ninguna entra.
    /// </summary>
    public static decimal? Promedio(IEnumerable<AsignaturaPeriodo> asignaturas)
    {
        ArgumentNullException.ThrowIfNull(asignaturas);
        decimal suma = 0m;
        decimal creditos = 0m;
        foreach (var a in asignaturas)
        {
            if (a.DefinitivaEfectiva is { } d)
            {
                suma += d * a.Creditos;
                creditos += a.Creditos;
            }
        }

        return creditos == 0m ? null : Redondeo.Promedio(suma / creditos);
    }

    /// <summary>Creditos matriculados: suma de todas las asignaturas, tengan o no definitiva.</summary>
    public static int CreditosMatriculados(IEnumerable<AsignaturaPeriodo> asignaturas)
    {
        ArgumentNullException.ThrowIfNull(asignaturas);
        return asignaturas.Sum(a => a.Creditos);
    }

    /// <summary>Prueba academica si promedio &lt; 3.0 (Art. 20).</summary>
    public static SituacionAcademica Situacion(decimal? promedio) => promedio switch
    {
        null => SituacionAcademica.NoDisponible,
        < UmbralPruebaAcademica => SituacionAcademica.PruebaAcademica,
        _ => SituacionAcademica.Normal,
    };
}

namespace TutorFlow.Domain.Academico;

public enum ResultadoBeca
{
    Cumple,
    NoCumple,
    NoDeterminable,
}

public enum RequisitoBeca
{
    Promedio,
    SinAsignaturasPerdidas,
    CreditosMatriculados,
}

public enum EstadoRequisito
{
    Cumple,
    NoCumple,
    NoDeterminable,
}

/// <summary>Detalle de un requisito: <see cref="Observado"/> es el valor medido (null si no disponible); <see cref="Exigido"/> el umbral.</summary>
public sealed record RequisitoBecaEvaluado(RequisitoBeca Requisito, EstadoRequisito Estado, decimal? Observado, decimal Exigido);

public sealed record EvaluacionBeca(ResultadoBeca Resultado, IReadOnlyList<RequisitoBecaEvaluado> Requisitos);

/// <summary>Beca por rendimiento academico (bienestar_y_becas.md 3.1; SPEC 5.8). TutorFlow informa, no otorga.</summary>
public static class Beca
{
    public const decimal PromedioMinimo = 4.30m;
    public const int CreditosMinimos = 12;

    public static EvaluacionBeca Evaluar(IEnumerable<AsignaturaPeriodo> asignaturas)
    {
        ArgumentNullException.ThrowIfNull(asignaturas);
        var lista = asignaturas.ToList();

        var promedio = ResumenAcademico.Promedio(lista);
        var creditos = ResumenAcademico.CreditosMatriculados(lista);
        var hayCortesPendientes = lista.Any(a => a.Definitiva is null);
        var hayAsistenciaDesconocida = lista.Any(a => a.PierdePorInasistencia is null);

        // Promedio: con cortes pendientes puede subir; con asistencia desconocida puede bajar.
        EstadoRequisito estadoPromedio;
        if (promedio is null)
        {
            estadoPromedio = EstadoRequisito.NoDeterminable;
        }
        else if (promedio.Value >= PromedioMinimo)
        {
            estadoPromedio = hayCortesPendientes || hayAsistenciaDesconocida
                ? EstadoRequisito.NoDeterminable
                : EstadoRequisito.Cumple;
        }
        else
        {
            estadoPromedio = hayCortesPendientes ? EstadoRequisito.NoDeterminable : EstadoRequisito.NoCumple;
        }

        // Perdidas: una perdida conocida ya falla; si no, lo pendiente o desconocido deja indeterminado.
        var perdidas = lista.Count(a => a.Perdida);
        EstadoRequisito estadoPerdidas;
        if (perdidas > 0)
        {
            estadoPerdidas = EstadoRequisito.NoCumple;
        }
        else if (hayCortesPendientes || hayAsistenciaDesconocida)
        {
            estadoPerdidas = EstadoRequisito.NoDeterminable;
        }
        else
        {
            estadoPerdidas = EstadoRequisito.Cumple;
        }

        var estadoCreditos = creditos >= CreditosMinimos ? EstadoRequisito.Cumple : EstadoRequisito.NoCumple;

        var requisitos = new List<RequisitoBecaEvaluado>
        {
            new(RequisitoBeca.Promedio, estadoPromedio, promedio, PromedioMinimo),
            new(RequisitoBeca.SinAsignaturasPerdidas, estadoPerdidas, perdidas, 0),
            new(RequisitoBeca.CreditosMatriculados, estadoCreditos, creditos, CreditosMinimos),
        };

        ResultadoBeca resultado;
        if (requisitos.Any(r => r.Estado == EstadoRequisito.NoCumple))
        {
            resultado = ResultadoBeca.NoCumple;
        }
        else if (requisitos.Any(r => r.Estado == EstadoRequisito.NoDeterminable))
        {
            resultado = ResultadoBeca.NoDeterminable;
        }
        else
        {
            resultado = ResultadoBeca.Cumple;
        }

        return new EvaluacionBeca(resultado, requisitos);
    }
}

namespace TutorFlow.Domain.Authorization;

/// <summary>
/// Implementacion pura y determinista de la matriz de SPEC 6.1. Sin E/S, sin estado, sin LLM.
/// Fail-closed: id o programa nulo/vacio/desconocido, tipo de recurso o rol no reconocido -> denegar.
/// Los datos de coordinadores no se exponen a nadie.
/// </summary>
public sealed class AuthorizationPolicy : IAuthorizationPolicy
{
    public DecisionAutorizacion Authorize(PrincipalAcademico principal, RecursoAcademico recurso)
    {
        ArgumentNullException.ThrowIfNull(principal);
        ArgumentNullException.ThrowIfNull(recurso);

        return recurso.Tipo switch
        {
            TipoRecurso.Reglamento => DecisionAutorizacion.Permitir(),
            TipoRecurso.DatosEstudiante => AutorizarDatosEstudiante(principal, recurso),
            TipoRecurso.ProgramaEstudiantes => AutorizarPrograma(principal, recurso),
            TipoRecurso.DatosCoordinador => DecisionAutorizacion.Denegar("datos_coordinador"),
            _ => DecisionAutorizacion.Denegar("recurso_desconocido"),
        };
    }

    private static DecisionAutorizacion AutorizarDatosEstudiante(PrincipalAcademico principal, RecursoAcademico recurso)
    {
        switch (principal.Rol)
        {
            case RolAcademico.Estudiante:
                return !string.IsNullOrEmpty(recurso.Id) && string.Equals(recurso.Id, principal.Id, StringComparison.Ordinal)
                    ? DecisionAutorizacion.Permitir()
                    : DecisionAutorizacion.Denegar("estudiante_ajeno");
            case RolAcademico.Coordinador:
                return ProgramaCoordinado(principal, recurso.ProgramaId)
                    ? DecisionAutorizacion.Permitir()
                    : DecisionAutorizacion.Denegar("fuera_de_programa");
            default:
                return DecisionAutorizacion.Denegar("rol_desconocido");
        }
    }

    private static DecisionAutorizacion AutorizarPrograma(PrincipalAcademico principal, RecursoAcademico recurso)
    {
        if (principal.Rol != RolAcademico.Coordinador)
        {
            return DecisionAutorizacion.Denegar("listado_solo_coordinador");
        }

        return ProgramaCoordinado(principal, recurso.ProgramaId)
            ? DecisionAutorizacion.Permitir()
            : DecisionAutorizacion.Denegar("fuera_de_programa");
    }

    private static bool ProgramaCoordinado(PrincipalAcademico principal, string? programaId)
    {
        if (string.IsNullOrEmpty(programaId))
        {
            return false;
        }

        foreach (var p in principal.ProgramasCoordinados)
        {
            if (string.Equals(p, programaId, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }
}

